CREATE TABLE IF NOT EXISTS cms_content_types(id BIGSERIAL PRIMARY KEY,content_key VARCHAR(80) NOT NULL UNIQUE,label VARCHAR(160) NOT NULL,singular_label VARCHAR(160) NOT NULL,public BOOLEAN NOT NULL DEFAULT TRUE,hierarchical BOOLEAN NOT NULL DEFAULT FALSE,supports_json TEXT NOT NULL DEFAULT '["title","editor"]',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_taxonomies(id BIGSERIAL PRIMARY KEY,taxonomy_key VARCHAR(80) NOT NULL UNIQUE,label VARCHAR(160) NOT NULL,singular_label VARCHAR(160) NOT NULL,hierarchical BOOLEAN NOT NULL DEFAULT FALSE,public BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_terms(id BIGSERIAL PRIMARY KEY,taxonomy_id BIGINT NOT NULL REFERENCES cms_taxonomies(id) ON DELETE CASCADE,parent_id BIGINT REFERENCES cms_terms(id) ON DELETE SET NULL,slug VARCHAR(190) NOT NULL,name VARCHAR(255) NOT NULL,description TEXT NOT NULL DEFAULT '',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(taxonomy_id,slug));
CREATE INDEX IF NOT EXISTS idx_cms_terms_taxonomy ON cms_terms(taxonomy_id,parent_id,name);
CREATE TABLE IF NOT EXISTS cms_term_relationships(page_id BIGINT NOT NULL REFERENCES cms_pages(id) ON DELETE CASCADE,term_id BIGINT NOT NULL REFERENCES cms_terms(id) ON DELETE CASCADE,position INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(page_id,term_id));
CREATE TABLE IF NOT EXISTS cms_autosaves(id BIGSERIAL PRIMARY KEY,page_id BIGINT REFERENCES cms_pages(id) ON DELETE CASCADE,actor_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,content_hash VARCHAR(64) NOT NULL,title TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',metadata_json TEXT NOT NULL DEFAULT '{}',saved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(page_id,actor_id));
ALTER TABLE cms_pages ADD COLUMN IF NOT EXISTS trash_status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK(trash_status IN('active','trash'));
ALTER TABLE cms_pages ADD COLUMN IF NOT EXISTS trashed_at TIMESTAMP;
ALTER TABLE cms_pages ADD COLUMN IF NOT EXISTS trashed_by BIGINT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE cms_page_revisions ADD COLUMN IF NOT EXISTS revision_kind VARCHAR(24) NOT NULL DEFAULT 'manual' CHECK(revision_kind IN('manual','autosave','restore','pre-trash'));
ALTER TABLE cms_page_revisions ADD COLUMN IF NOT EXISTS content_hash VARCHAR(64) NOT NULL DEFAULT '';
ALTER TABLE cms_page_revisions ADD COLUMN IF NOT EXISTS metadata_json TEXT NOT NULL DEFAULT '{}';
INSERT INTO cms_content_types(content_key,label,singular_label,public,hierarchical,supports_json) VALUES('page','صفحه','صفحه',TRUE,TRUE,'["title","editor","revisions","author","custom-fields"]'),('post','نوشته','نوشته',TRUE,FALSE,'["title","editor","revisions","author","excerpt","thumbnail","custom-fields"]') ON CONFLICT(content_key) DO NOTHING;
INSERT INTO cms_taxonomies(taxonomy_key,label,singular_label,hierarchical,public) VALUES('category','دسته‌بندی‌ها','دسته‌بندی',TRUE,TRUE),('tag','برچسب‌ها','برچسب',FALSE,TRUE) ON CONFLICT(taxonomy_key) DO NOTHING;
INSERT INTO schema_migrations(version) VALUES('10.11.0') ON CONFLICT(version) DO NOTHING;